"use client";

import { useEffect, useMemo, useState } from "react";
import type { ChatStats, StoryMode } from "@/lib/types";
import { validateBrowserPremiumEntitlement } from "@/platform/billing/client-entitlement";
import { downloadStoryCard, downloadStorySet, shareStoryCard, type StoryCardPreset } from "@/platform/export/story-card";
import { composeThreadTale } from "@/platform/story/compose";
import { getStoryModeConfig } from "@/platform/story/modes";
import { getStoryTheme, storyThemeBackground } from "@/platform/story/themes";
import { trackProductEvent } from "@/platform/telemetry/client";
import type { StoryThemeId } from "@/platform/types";
import { AIEnrichmentPanel } from "./AIEnrichmentPanel";
import { CinematicStoryPlayer } from "./CinematicStoryPlayer";
import { CloudSavePanel } from "./CloudSavePanel";
import { ExportToolbar, StoryPrivacyBadge, ThemeSelector } from "./MemoryCinemaControls";
import { PremiumPanel } from "./PremiumPanel";

export function StoryChapterDeck({ stats, mode }: { stats: ChatStats; mode: StoryMode }) {
  const chapters = useMemo(() => composeThreadTale(stats, mode), [stats, mode]);
  const config = getStoryModeConfig(mode);
  const [active, setActive] = useState(0);
  const [preset, setPreset] = useState<StoryCardPreset>("vertical");
  const [themeId, setThemeId] = useState<StoryThemeId>("midnight");
  const [premiumUnlocked, setPremiumUnlocked] = useState(false);
  const [exporting, setExporting] = useState(false);
  const [message, setMessage] = useState("");
  const chapter = chapters[Math.min(active, Math.max(0, chapters.length - 1))];
  const theme = getStoryTheme(themeId);

  useEffect(() => { trackProductEvent("story_viewed", "threadtales", mode); }, [stats, mode]);
  useEffect(() => { let cancelled = false; void validateBrowserPremiumEntitlement().then((valid) => { if (!cancelled) { setPremiumUnlocked(valid); if (valid) setThemeId(config.theme); } }); return () => { cancelled = true; }; }, [config.theme]);

  if (!chapter) return null;

  async function exportCurrent() { setExporting(true); setMessage(""); try { await downloadStoryCard(chapter, preset, true, themeId); trackProductEvent("story_exported", "threadtales", mode); setMessage("Your chapter is ready as a social-native PNG."); } finally { setExporting(false); } }
  async function shareCurrent() { setExporting(true); setMessage(""); try { const shared = await shareStoryCard(chapter, preset, true, themeId); if (!shared) { await downloadStoryCard(chapter, preset, true, themeId); setMessage("Native file sharing is unavailable in this browser, so the PNG was downloaded instead."); } else { trackProductEvent("share_created", "threadtales", mode); setMessage("Share sheet opened with this derived story artifact."); } } finally { setExporting(false); } }
  async function exportSafeStory() { if (!premiumUnlocked) { setMessage("Full-story image sets are a Premium artifact. Your complete analysis and individual Midnight cards remain free."); return; } setExporting(true); setMessage(""); try { const count = await downloadStorySet(chapters, preset, true, themeId, false); trackProductEvent("story_exported", "threadtales", mode); setMessage(`Prepared ${count} share-safe story cards. Sensitive name/language chapters were excluded.`); } finally { setExporting(false); } }
  function chooseTheme(next: StoryThemeId) { const requested = getStoryTheme(next); if (requested.premium && !premiumUnlocked) { setMessage(`${requested.label} is a Premium artifact theme. Midnight remains fully available for free.`); return; } setThemeId(next); setMessage(""); }

  return <>
    <section className="story chapter-deck mc-story-deck" aria-label={`${config.label} story chapters`}>
      <div className="chapter-head mc-story-deck-head"><div><span className="story-summary-kicker">Story engine</span><h3>{config.label} · {chapters.length} chapters</h3><p>The complete deterministic analysis remains free. Story themes change the artifact—not the facts—and sensitive chapters stay local unless you explicitly choose otherwise.</p></div></div>
      <div className="mc-story-workbench">
        <div className="mc-story-canvas">
          <div className="chapter-preview" data-preset={preset} style={{ background: storyThemeBackground(theme), color: theme.foreground }}>
            <small>{chapter.type.replace("-", " ")}</small>
            <h3>{chapter.title}</h3>
            {chapter.metric !== undefined ? <strong>{chapter.metric}</strong> : null}
            {chapter.subtitle ? <span>{chapter.subtitle}</span> : null}
            {chapter.supportingText ? <p>{chapter.supportingText}</p> : null}
            <StoryPrivacyBadge sensitive={chapter.privacyLevel !== "safe"} />
          </div>
          <div className="chapter-nav" aria-label="Story chapter navigation">
            <button className="btn btn-soft" onClick={() => setActive((value) => Math.max(0, value - 1))} disabled={active === 0}>← Previous</button>
            <div className="chapter-dots" aria-label={`Chapter ${active + 1} of ${chapters.length}`}>{chapters.map((item, index) => <button key={item.id} className={index === active ? "active" : ""} aria-label={`Open chapter ${index + 1}`} aria-current={index === active ? "step" : undefined} onClick={() => setActive(index)} />)}</div>
            <button className="btn btn-soft" onClick={() => setActive((value) => Math.min(chapters.length - 1, value + 1))} disabled={active === chapters.length - 1}>Next →</button>
          </div>
        </div>
        <ThemeSelector value={themeId} premiumUnlocked={premiumUnlocked} onChange={chooseTheme} />
      </div>
      <ExportToolbar preset={preset} exporting={exporting} premiumUnlocked={premiumUnlocked} onPresetChange={setPreset} onDownload={() => void exportCurrent()} onShare={() => void shareCurrent()} onExportSet={() => void exportSafeStory()} />
      {message ? <div className="notice mc-export-status" role="status" aria-live="polite">{message}</div> : null}
    </section>
    <CinematicStoryPlayer chapters={chapters} themeId={themeId}/><PremiumPanel stats={stats} mode={mode}/><CloudSavePanel stats={stats} mode={mode}/><AIEnrichmentPanel stats={stats} mode={mode}/>
  </>;
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useSearchParams } from "next/navigation";
import { MIN_CHAT_MESSAGES, tooFewMessagesError, validateChatFileMetadata, validateRawChatText } from "@/lib/import-validation";
import { makeSampleChat } from "@/lib/sample";
import type { ChatStats, DateOrder, StoryMode } from "@/lib/types";
import { isStoryMode, STORY_MODES } from "@/platform/story/modes";
import { trackProductEvent } from "@/platform/telemetry/client";
import { analyzeThreadTaleInput } from "@/platform/threadtales/worker-client";
import { buildThreadTalesLocalLore, type ThreadTalesLocalLore } from "@/platform/threadtales/lore";
import { LocalLorePanel } from "./LocalLorePanel";
import { ProcessingReveal } from "./ProcessingReveal";
import { WrappedStory } from "./WrappedStory";

export function UploadAnalyzer() {
  const [stats, setStats] = useState<ChatStats | null>(null);
  const [lore, setLore] = useState<ThreadTalesLocalLore | null>(null);
  const [error, setError] = useState("");
  const [warning, setWarning] = useState("");
  const [busy, setBusy] = useState(false);
  const [dragging, setDragging] = useState(false);
  const [dateOrder, setDateOrder] = useState<DateOrder>("auto");
  const [storyMode, setStoryMode] = useState<StoryMode>("friends");
  const fileRef = useRef<HTMLInputElement>(null);
  const abortRef = useRef<AbortController | null>(null);
  const requestRef = useRef(0);
  const search = useSearchParams();

  useEffect(() => () => abortRef.current?.abort(), []);

  const analyzeText = useCallback(async (text: string, name = "threadtales-demo.txt", type = "text/plain") => {
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;
    const requestId = ++requestRef.current;
    setBusy(true); setError(""); setWarning(""); setStats(null); setLore(null);
    trackProductEvent("analysis_started", "threadtales");
    await new Promise<void>((resolve) => window.setTimeout(resolve, 0));
    try {
      const parsed = await analyzeThreadTaleInput({ name, type, size: new Blob([text]).size, text }, dateOrder, controller.signal);
      if (requestId !== requestRef.current || controller.signal.aborted) return;
      if (parsed.messages.length < MIN_CHAT_MESSAGES) throw new Error(tooFewMessagesError(parsed.messages.length));
      setStats(parsed.stats);
      setLore(buildThreadTalesLocalLore(parsed.messages));
      setWarning(parsed.warnings[0] ?? "");
      trackProductEvent("analysis_completed", "threadtales");
      window.setTimeout(() => document.getElementById("results")?.scrollIntoView({ behavior: "smooth" }), 80);
    } catch (cause) {
      if (requestId !== requestRef.current) return;
      setStats(null); setLore(null);
      setError(cause instanceof Error && cause.name === "AbortError" ? "Analysis cancelled. You can choose another export whenever you're ready." : cause instanceof Error ? cause.message : "Something went wrong while reading that export.");
    } finally {
      if (requestId === requestRef.current) { setBusy(false); abortRef.current = null; }
    }
  }, [dateOrder]);

  useEffect(() => { const requestedMode = search.get("mode"); if (!isStoryMode(requestedMode)) return; const timer = window.setTimeout(() => setStoryMode(requestedMode), 0); return () => window.clearTimeout(timer); }, [search]);
  useEffect(() => { if (search.get("demo") !== "1" || stats || busy) return; const timer = window.setTimeout(() => void analyzeText(makeSampleChat()), 0); return () => window.clearTimeout(timer); }, [analyzeText, busy, search, stats]);

  async function handleFile(file?: File) {
    if (!file || busy) return;
    setStats(null); setLore(null); setError(""); setWarning("");
    const metadataError = validateChatFileMetadata(file);
    if (metadataError) { setError(metadataError); if (fileRef.current) fileRef.current.value = ""; return; }
    try {
      const text = await file.text();
      const textError = validateRawChatText(text);
      if (textError) { setError(textError); return; }
      await analyzeText(text, file.name, file.type || (file.name.toLowerCase().endsWith(".json") ? "application/json" : "text/plain"));
    } catch {
      setStats(null); setLore(null); setBusy(false);
      setError("I couldn't read that file. Please export a supported single chat and try again.");
    } finally { if (fileRef.current) fileRef.current.value = ""; }
  }

  function cancelAnalysis() { requestRef.current += 1; abortRef.current?.abort(); abortRef.current = null; setBusy(false); setStats(null); setLore(null); setWarning(""); setError("Analysis cancelled. You can choose another export whenever you're ready."); }
  function resetAnalysis() { requestRef.current += 1; abortRef.current?.abort(); abortRef.current = null; setStats(null); setLore(null); setError(""); setWarning(""); setDragging(false); setBusy(false); if (fileRef.current) fileRef.current.value = ""; fileRef.current?.focus(); }

  return <>
    <section className="uploader mc-uploader" aria-busy={busy}>
      <div className={`drop mc-drop ${dragging ? "active" : ""}`} onDragOver={(event) => { event.preventDefault(); if (!busy) setDragging(true); }} onDragLeave={() => setDragging(false)} onDrop={(event) => { event.preventDefault(); setDragging(false); void handleFile(event.dataTransfer.files[0]); }}>
        <div className="mc-drop-orb" aria-hidden="true"><span>↥</span></div>
        <span className="mc-drop-label">Private import</span>
        <h2>Drop your exported chat here</h2>
        <p>WhatsApp .txt and single-chat Telegram .json exports are processed locally. Raw messages are not uploaded to ThreadTales by default.</p>
        <input ref={fileRef} className="file-input" type="file" accept=".txt,.json,text/plain,application/json" aria-label="Choose WhatsApp text export or Telegram JSON export" onChange={(event) => void handleFile(event.target.files?.[0])} disabled={busy}/>
        <button className="btn btn-primary mc-upload-button" onClick={() => fileRef.current?.click()} disabled={busy}>{busy ? "Reading locally…" : "Choose chat export"}</button>
        <small className="mc-file-types">WhatsApp .txt · Telegram .json · no raw-chat database</small>
      </div>

      {busy ? <><ProcessingReveal/><div className="mc-cancel-row"><button className="btn btn-soft" onClick={cancelAnalysis}>Cancel analysis</button></div></> : <div className="controls mc-create-controls">
        <label><span>Story type</span><select className="select" value={storyMode} onChange={(event) => setStoryMode(event.target.value as StoryMode)}>{Object.values(STORY_MODES).map((mode) => <option key={mode.id} value={mode.id}>{mode.label}</option>)}</select></label>
        <label><span>Date interpretation</span><select className="select" value={dateOrder} onChange={(event) => setDateOrder(event.target.value as DateOrder)}><option value="auto">Auto / US-first</option><option value="mdy">MM/DD/YYYY</option><option value="dmy">DD/MM/YYYY</option></select></label>
        <button className="btn btn-soft" onClick={() => void analyzeText(makeSampleChat())}>Use demo chat</button>
      </div>}

      <div className="mc-upload-receipt"><span>◉ Raw messages stay in this browser</span><span>◉ No account required</span><span>◉ You control sharing</span></div>
      {warning ? <div className="notice" role="status">{warning}</div> : null}
      {error ? <div className="error" role="alert" aria-live="polite">{error}</div> : null}
    </section>

    {stats ? <section id="results" className="results mc-results" aria-live="polite"><div className="story controls mc-ready-bar"><div><span className="mc-ready-dot"/>Your private analysis is ready.</div><button className="btn btn-soft" onClick={resetAnalysis}>Analyze another chat</button></div><WrappedStory stats={stats} mode={storyMode}/>{lore ? <LocalLorePanel lore={lore}/> : null}</section> : null}
  </>;
}

"use client";
/* eslint-disable react-hooks/set-state-in-effect -- each product draft hydrates once from its own local key. */

import { useEffect, useMemo, useRef, useState } from "react";
import { downloadStoryCard } from "@/platform/export/story-card";
import type { StoryChapter } from "@/platform/types";
import { trackProductEvent } from "@/platform/telemetry/client";
import { worldBlueprints, type WorldSlug } from "@/products/worlds/config";

type WorldEvent = { id: string; date: string; title: string; detail?: string; people?: string; place?: string; extra?: string; kind: string };
type WorldState = { title: string; anchorDate: string; events: WorldEvent[] };
type ShareFields = { title: boolean; places: boolean };

const today = () => new Date().toISOString().slice(0, 10);
const blankEvent = (kind: string): Omit<WorldEvent, "id"> => ({ date: today(), title: "", detail: "", people: "", place: "", extra: "", kind });
const scalar = (value: unknown, limit = 180) => typeof value === "string" ? value.trim().slice(0, limit) : typeof value === "number" ? String(value) : "";

function parseCsv(text: string): WorldEvent[] {
  const [head, ...rows] = text.trim().split(/\r?\n/);
  if (!head || !rows.length) return [];
  const columns = head.split(",").map((item) => item.trim().toLowerCase());
  return rows.slice(0, 250).map((row, index) => {
    const values = row.split(",").map((item) => item.trim());
    const pick = (...names: string[]) => values[columns.findIndex((column) => names.includes(column))] ?? "";
    return { id: `csv-${index}-${crypto.randomUUID()}`, date: scalar(pick("date", "occurredat", "timestamp"), 20) || today(), title: scalar(pick("title", "event", "name", "milestone")) || `Imported event ${index + 1}`, detail: scalar(pick("description", "note", "details"), 500) || undefined, people: scalar(pick("people", "person", "platform")) || undefined, place: scalar(pick("place", "location")) || undefined, extra: scalar(pick("metric", "value", "song")) || undefined, kind: scalar(pick("kind", "type")) || "Imported" };
  });
}
function unfoldJson(value: unknown): WorldEvent[] {
  const root = value as { events?: unknown } | unknown[];
  const records = Array.isArray(root) ? root : Array.isArray(root?.events) ? root.events : root && typeof root === "object" ? [root] : [];
  return records.slice(0, 250).map((record, index) => {
    const item = record as Record<string, unknown>;
    return { id: `json-${index}-${crypto.randomUUID()}`, date: scalar(item.date ?? item.occurredAt ?? item.timestamp, 20) || today(), title: scalar(item.title ?? item.name ?? item.event) || `Imported event ${index + 1}`, detail: scalar(item.description ?? item.note ?? item.details, 500) || undefined, people: scalar(item.people ?? item.person ?? item.platform) || undefined, place: scalar(item.place ?? item.location) || undefined, extra: scalar(item.metric ?? item.value ?? item.song) || undefined, kind: scalar(item.kind ?? item.type) || "Imported" };
  });
}
function parseIcs(text: string): WorldEvent[] {
  return text.replace(/\r?\n[ \t]/g, "").split("BEGIN:VEVENT").slice(1, 251).map((block, index) => {
    const read = (name: string) => block.match(new RegExp(`^${name}(?:;[^:]*)?:(.+)$`, "mi"))?.[1]?.trim() ?? "";
    const rawDate = read("DTSTART");
    const date = /^\d{8}/.test(rawDate) ? `${rawDate.slice(0, 4)}-${rawDate.slice(4, 6)}-${rawDate.slice(6, 8)}` : today();
    return { id: `ics-${index}-${crypto.randomUUID()}`, date, title: read("SUMMARY") || `Calendar event ${index + 1}`, detail: scalar(read("DESCRIPTION"), 500) || undefined, place: scalar(read("LOCATION")) || undefined, kind: "Calendar" };
  });
}

export function WorldBuilder({ slug }: { slug: WorldSlug }) {
  const blueprint = worldBlueprints[slug]; const storageKey = `story-platform:world:${slug}:v1`;
  const [state, setState] = useState<WorldState>({ title: "", anchorDate: "", events: [] });
  const [draft, setDraft] = useState<Omit<WorldEvent, "id">>(() => blankEvent(blueprint.kinds[0]));
  const [editing, setEditing] = useState<string | null>(null); const [message, setMessage] = useState(""); const [shareFields, setShareFields] = useState<ShareFields>({ title: false, places: false }); const fileRef = useRef<HTMLInputElement>(null);
  useEffect(() => { try { const saved = window.localStorage.getItem(storageKey); if (!saved) return; const parsed = JSON.parse(saved) as WorldState; if (typeof parsed.title === "string" && Array.isArray(parsed.events)) setState({ title: parsed.title, anchorDate: parsed.anchorDate ?? "", events: parsed.events.filter((event) => event && typeof event.title === "string").slice(0, 500) }); } catch { window.localStorage.removeItem(storageKey); } }, [storageKey]);
  useEffect(() => { window.localStorage.setItem(storageKey, JSON.stringify(state)); }, [state, storageKey]);
  const sorted = useMemo(() => [...state.events].sort((a, b) => a.date.localeCompare(b.date)), [state.events]);
  const places = useMemo(() => [...new Set(state.events.map((event) => event.place).filter(Boolean))] as string[], [state.events]);
  const chapter = useMemo<StoryChapter>(() => ({ id: `${slug}-world`, type: "timeline", title: state.title || blueprint.titlePlaceholder, subtitle: state.events.length ? `${state.events.length} chosen moments · ${places.length} places` : "Add a first memory to begin", metric: state.events.length || undefined, supportingText: blueprint.visualCopy, privacyLevel: "safe", renderVariant: "timeline" }), [blueprint, places.length, slug, state.events.length, state.title]);
  function addOrUpdate() { if (!draft.title.trim()) { setMessage(`Add a ${blueprint.eventLabel.toLowerCase()} first.`); return; } const event: WorldEvent = { ...draft, id: editing ?? crypto.randomUUID(), title: draft.title.trim(), date: draft.date || today(), detail: draft.detail?.trim() || undefined, people: draft.people?.trim() || undefined, place: draft.place?.trim() || undefined, extra: draft.extra?.trim() || undefined }; setState((current) => ({ ...current, events: editing ? current.events.map((item) => item.id === editing ? event : item) : [...current.events, event] })); setEditing(null); setDraft(blankEvent(blueprint.kinds[0])); setMessage(editing ? "Memory updated locally." : "Memory added to this local world."); trackProductEvent("story_viewed", slug); }
  function edit(event: WorldEvent) { const { id, ...next } = event; setEditing(id); setDraft(next); }
  function remove(id: string) { setState((current) => ({ ...current, events: current.events.filter((event) => event.id !== id) })); }
  async function importFile(file: File | undefined) { if (!file) return; if (file.size > 2_000_000) { setMessage("Choose a file under 2 MB; imports stay local in this browser."); return; } try { const text = await file.text(); const incoming = file.name.toLowerCase().endsWith(".ics") ? parseIcs(text) : file.name.toLowerCase().endsWith(".csv") ? parseCsv(text) : unfoldJson(JSON.parse(text)); if (!incoming.length) { setMessage("No supported entries were found. Use JSON records or a CSV with title and date columns."); return; } setState((current) => ({ ...current, events: [...current.events, ...incoming].slice(0, 500) })); setMessage(`Imported ${incoming.length} local ${incoming.length === 1 ? "entry" : "entries"}. Review each one before sharing.`); } catch { setMessage("That file could not be read. Use valid JSON, CSV, or an exported .ics calendar."); } }
  function downloadBackup() { const backup = { version: 1, product: slug, title: state.title || blueprint.titlePlaceholder, anchorDate: state.anchorDate || undefined, events: sorted }; const href = URL.createObjectURL(new Blob([JSON.stringify(backup, null, 2)], { type: "application/json" })); const anchor = document.createElement("a"); anchor.href = href; anchor.download = `${slug}-local-backup.json`; anchor.click(); window.setTimeout(() => URL.revokeObjectURL(href), 500); trackProductEvent("story_exported", slug); }
  async function copySelectedSafeSummary() { const summary = { version: 1, product: slug, eventCount: state.events.length, ...(shareFields.title ? { title: state.title || blueprint.titlePlaceholder } : {}), ...(shareFields.places ? { places: places.slice(0, 8) } : {}), dateRange: sorted.length ? { start: sorted[0].date, end: sorted.at(-1)?.date } : undefined, kinds: [...new Set(state.events.map((event) => event.kind))] }; await navigator.clipboard.writeText(JSON.stringify(summary)); setMessage("Copied a selected share summary. Notes, people labels, raw files, titles and places stay out unless you opt in."); trackProductEvent("share_created", slug); }
  function reset() { if (!window.confirm(`Delete this local ${blueprint.titleLabel.toLowerCase()} and its ${state.events.length} memories from this browser?`)) return; window.localStorage.removeItem(storageKey); setState({ title: "", anchorDate: "", events: [] }); setEditing(null); setDraft(blankEvent(blueprint.kinds[0])); setMessage("The local world was deleted from this browser."); }
  return <div className="product-builder" id={`${slug}-builder`} data-product={slug}>
    <section className="story product-workspace">
      <div className="chapter-head"><div><span className="story-summary-kicker">{blueprint.eyebrow}</span><h2>{blueprint.visualTitle}</h2><p>{blueprint.visualCopy}</p></div></div>
      <div className="builder-card"><h3>Start your world</h3><div className="builder-grid"><label>{blueprint.titleLabel}<input className="share-input" aria-label={blueprint.titleLabel} value={state.title} maxLength={100} onChange={(event) => setState((current) => ({ ...current, title: event.target.value }))} placeholder={blueprint.titlePlaceholder}/></label><label>{blueprint.dateLabel}<input className="share-input" aria-label={blueprint.dateLabel} type="date" value={state.anchorDate} onChange={(event) => setState((current) => ({ ...current, anchorDate: event.target.value }))}/></label></div><div className="premium-actions"><button className="btn btn-soft" onClick={() => fileRef.current?.click()}>Import local file</button><input ref={fileRef} aria-label={`Import ${blueprint.eyebrow} file`} className="file-input" type="file" accept=".json,.csv,.ics,application/json,text/csv,text/calendar" onChange={(event) => void importFile(event.target.files?.[0])}/><button className="btn btn-soft" onClick={downloadBackup} disabled={!state.events.length}>Download local backup</button><button className="btn btn-soft" onClick={reset} disabled={!state.title && !state.events.length}>Delete world</button></div><p className="notice">{blueprint.acceptsIcs ? "Local .ics, JSON and CSV imports are supported. " : "Local JSON and CSV imports are supported. "}{blueprint.acceptsMetrics ? "Metrics are imported as entries; no account connector is claimed. " : ""}Imports stay in this browser.</p></div>
      <div className="builder-card"><h3>{editing ? `Edit ${blueprint.eventLabel.toLowerCase()}` : `Add a ${blueprint.eventLabel.toLowerCase()}`}</h3><div className="builder-grid"><label>{blueprint.eventLabel}<input className="share-input" aria-label={`${blueprint.eyebrow} event title`} value={draft.title} maxLength={140} onChange={(event) => setDraft((current) => ({ ...current, title: event.target.value }))} placeholder={blueprint.eventPlaceholder}/></label><label>Date<input className="share-input" aria-label={`${blueprint.eyebrow} event date`} type="date" value={draft.date} onChange={(event) => setDraft((current) => ({ ...current, date: event.target.value }))}/></label><label>Kind<select className="select" aria-label={`${blueprint.eyebrow} event kind`} value={draft.kind} onChange={(event) => setDraft((current) => ({ ...current, kind: event.target.value }))}>{blueprint.kinds.map((kind) => <option key={kind}>{kind}</option>)}</select></label><label>{blueprint.peopleLabel}<input className="share-input" value={draft.people} maxLength={120} onChange={(event) => setDraft((current) => ({ ...current, people: event.target.value }))}/></label><label>{blueprint.placeLabel}<input className="share-input" value={draft.place} maxLength={120} onChange={(event) => setDraft((current) => ({ ...current, place: event.target.value }))}/></label><label>{blueprint.extraLabel}<input className="share-input" value={draft.extra} maxLength={120} onChange={(event) => setDraft((current) => ({ ...current, extra: event.target.value }))} placeholder={blueprint.extraPlaceholder}/></label><label>{blueprint.detailLabel}<input className="share-input" value={draft.detail} maxLength={500} onChange={(event) => setDraft((current) => ({ ...current, detail: event.target.value }))} placeholder={blueprint.detailPlaceholder}/></label></div><div className="premium-actions"><button className="btn btn-primary" onClick={addOrUpdate}>{editing ? "Save changes" : "Add to world"}</button>{editing ? <button className="btn btn-soft" onClick={() => { setEditing(null); setDraft(blankEvent(blueprint.kinds[0])); }}>Cancel edit</button> : null}</div></div>
      {message ? <div className="notice" role="status">{message}</div> : null}
